:* {{Tlx|dir|lang{{=}}en}}, for {{#language:en|en}} (<span lang="en" dir="{{dir|en}}">{{#language:en}}</span>), returns <code>{{dir|lang=en}}</code>. 
:* {{Tlx|dir|ar}}, for {{#language:ar|en}}  (<span lang="ar" dir="{{dir|ar}}">{{#language:ar}}</span>), returns <code>{{dir|ar}}</code>.
:* {{Tlx|dir|yi}}, for {{#language:yi|en}}  (<span lang="yi" dir="{{dir|yi}}">{{#language:yi}}</span>), returns <code>{{dir|yi}}</code>.
:* {{Tlx|dir|2{{=}}right|3{{=}}left}}, for the current user language which is {{#language:{{uselang}}|en}} (<span lang="{{uselang}}" dir="{{dir|{{uselang}}}}">{{#language:{{uselang}}}}</span>), returns <code>{{dir|2=right|3=left}}</code>.
:* {{Tlx|dir|rtl{{=}}right|ltr{{=}}left}}, for the current user language which is {{#language:{{uselang}}|en}} (<span lang="{{uselang}}" dir="{{dir|{{uselang}}}}">{{#language:{{uselang}}}}</span>), returns <code>{{dir|rtl=right|ltr=left}}</code>.
:* {{Tlx|dir|en|right|left}}, for {{#language:en|en}} (<span lang="en" dir="{{dir|en}}">{{#language:en}}</span>),  returns <code>{{dir|en|right|left}}</code>. 
:* {{Tlx|dir|ar|right|left}}, for {{#language:ar|en}} (<span lang="ar" dir="{{dir|ar}}">{{#language:ar}}</span>),  returns <code>{{dir|ar|right|left}}</code>.
:* {{Tlx|dir|yi|right|left}}, for {{#language:yi|en}} (<span lang="yi" dir="{{dir|yi}}">{{#language:yi}}</span>),  returns <code>{{dir|yi|right|left}}</code>.
:* {{Tlx|dir|lang{{=}}yi|rtl{{=}}right|ltr{{=}}left}}, for {{#language:yi|en}} (<span lang="yi" dir="{{dir|yi}}">{{#language:yi}}</span>), returns <code>{{dir|lang=yi|rtl=right|ltr=left}}</code>.

